<?php declare(strict_types=1);namespace App\Models;use App\Core\DB;final class Order extends Model{protected static string $table='orders';protected static array $json=['billing'];public static function forUser(int $U):array{return static::castAll(static::query()->where('user_id',$U)->orderBy('id','DESC')->get());}public static function withRelations(int $f):?array{$g=DB::fetch('SELECT o.*, p.slug AS plan_slug, p.name AS plan_name, u.email AS user_email, u.name AS user_name FROM {{orders}} o JOIN {{plans}} p ON p.id = o.plan_id JOIN {{users}} u ON u.id = o.user_id WHERE o.id = ?',[$f]);if(!$g){return null;}$g=static::cast($g);$g['plan_name']=json_decode((string)$g['plan_name'],true)?:[];return $g;}}